// spec: specs/session-auth.md (1.2, 2.1) · кейс SA-05 · запасной путь (MCP playwright-test отключён)
// seed: tests/seed.spec.ts (гость) + tests/seed.parent-b.spec.ts (только чтобы взять публичный apikey из запроса приложения)
import { test, expect } from '../../fixtures';
import { captureSupabase, visibleText } from './session-auth.helpers';

/** Провайдеры входа, которые разрешены (вход по почте/телефону); всё остальное в external должно быть false. */
const ALLOWED = new Set(['email', 'phone']);

/** Кнопки/ссылки внешнего входа на экране входа (не должно быть ни одной). */
// (без «אפל» — совпадает с «אפליקציה»; sso — только отдельным словом)
const SSO_RE = /google|apple|microsoft|facebook|azure|github|\bsso\b|גוגל|מיקרוסופט|משרד החינוך|הזדהות/i;

test.use({ viewport: { width: 1280, height: 800 } });

test.describe('Сессия и права — внешний вход выключен', () => {
  test('auth/v1/settings: все внешние провайдеры выключены @desktop @prod-safe #a337fd', async ({ asUser }) => {
    const parent = await asUser('parent-b');
    const sb = await captureSupabase(parent, '/children');

    const resp = await parent.request.get(`${sb.base}/auth/v1/settings`, { headers: { apikey: sb.apikey } });
    expect(resp.status()).toBe(200);
    const external: Record<string, boolean> = (await resp.json()).external;
    expect(external, 'есть блок external').toBeTruthy();

    // AC6 «מיפוי זהות חיצונית נשאר כבוי»
    const enabled = Object.entries(external).filter(([k, v]) => v === true && !ALLOWED.has(k)).map(([k]) => k);
    expect(enabled, `включены внешние провайдеры: ${enabled.join(', ')}`).toEqual([]);
    expect(external.anonymous_users, 'анонимный вход выключен').toBe(false);
  });

  test('/sign-in у гостя: нет кнопок внешнего входа @desktop @prod-safe #a337fd', async ({ asUser }) => {
    const guest = await asUser('guest');
    await guest.goto('/sign-in');
    // Экран входа загрузился: видна кнопка «כניסה» (r5-t6-signin.json: кнопки «השתק», «כניסה»)
    await expect(guest.getByRole('button', { name: 'כניסה', exact: true }).filter({ visible: true }).first()).toBeVisible();

    await expect(guest.getByRole('button', { name: SSO_RE }).filter({ visible: true })).toHaveCount(0);
    await expect(guest.getByRole('link', { name: SSO_RE }).filter({ visible: true })).toHaveCount(0);
    await expect(guest.locator('a[href*="/authorize"]').filter({ visible: true })).toHaveCount(0);
    await expect(visibleText(guest, SSO_RE)).toHaveCount(0);
  });
});
